const GENRES = {all:'전체 장르',modern:'일상·현대',fantasy:'판타지',medieval:'중세',historical:'사극·동양·시대물',sf:'SF',apocalypse:'아포칼립스',verse:'버스 세계관'};
function eligible(category, options) {
  if (!options.groups.includes(category.group)) return [];
  if (options.audience === 'male' && category.verse) return [];
  return category.items.filter(item => options.genre === 'all' || item.genres.includes('common') || item.genres.includes(options.genre));
}
function assemble(name, rows) {
  const all = rows.flatMap(row => row.items);
  const roles = new Set(all.flatMap(item => item.roles));
  const extra = roles.has('dom') && roles.has('sub') && !all.some(item => /스위치|Switch/i.test(item.text));
  const lines = rows.map(row => `${row.name}:${row.items.map(item => item.text).join(', ')}`);
  if (extra) lines.push('성적 성향:스위치');
  return `#${name} 정보\n${lines.join('\n')}`;
}
function generate(data, options, random = Math.random) {
  const name = options.name.trim();
  if (!name || /[\r\n]/.test(name)) throw new Error('페소 또는 캐릭터 이름을 한 줄로 입력하세요.');
  if (![500,2000].includes(options.limit)) throw new Error('현재 글자 제한을 확인할 수 없습니다.');
  const existing = options.existingText ?? '';
  const prefix = options.writeMode === 'append' && existing.length
    ? existing + (existing.endsWith('\n\n') ? '' : existing.endsWith('\n') ? '\n' : '\n\n')
    : '';
  const rows = [];
  for (const category of data) {
    if (!options.selected[category.id]) continue;
    const pool = eligible(category, options);
    // Categories excluded by top-level filters are inactive, never secretly sampled.
    if (!pool.length) continue;
    const count = options.multiple ? Number(options.counts[category.id] ?? 1) : 1;
    if (!Number.isInteger(count) || count < 1 || count > pool.length) throw new Error(`${category.name}: 선택 가능한 ${pool.length}개 이내로 개수를 지정하세요.`);
    rows.push({name:category.name,pool,count});
  }
  if (!rows.length) throw new Error('현재 조건에서 뽑을 카테고리를 하나 이상 선택하세요.');
  const lowerRows = rows.map(row => ({name:row.name,items:[...row.pool].sort((a,b)=>a.text.length-b.text.length).slice(0,row.count)}));
  // A true lower bound excludes the optional switch line.
  const lower = prefix + `#${name} 정보\n` + lowerRows.map(row=>`${row.name}:${row.items.map(item=>item.text).join(', ')}`).join('\n');
  if (lower.length > options.limit) throw new Error(`최소 ${lower.length}자라 ${options.limit}자에 들어가지 않습니다. 카테고리나 개수를 줄이세요.`);
  for (let attempt=1; attempt<=2000; attempt++) {
    const picked = rows.map(row => {
      const pool = [...row.pool];
      for (let i=0;i<row.count;i++) {
        const j=i+Math.floor(random()*(pool.length-i));
        [pool[i],pool[j]]=[pool[j],pool[i]];
      }
      return {name:row.name,items:pool.slice(0,row.count)};
    });
    const text = prefix + assemble(name,picked);
    if (text.length <= options.limit) return {text,attempt,rows:picked};
  }
  throw new Error('2,000회 재추첨해도 제한을 만족하지 못했습니다. 카테고리나 개수를 줄여 다시 생성하세요.');
}
function detectLimit(editor, scope) {
  if ([500,2000].includes(editor.maxLength)) return {limit:editor.maxLength,source:'입력칸 제한'};
  const text = scope.innerText ?? scope.textContent ?? '';
  const matches = [...text.matchAll(/\d[\d,]*\s*\/\s*(500|2,?000)(?!\d)/g)];
  const limits = [...new Set(matches.map(m=>Number(m[1].replace(',',''))))];
  return limits.length === 1 ? {limit:limits[0],source:'화면 글자 수'} : null;
}

