let mount=null, frame=0;
const visible = el => !!el?.isConnected && el.getClientRects().length>0 && !el.closest('[hidden],[inert],[aria-hidden="true"]');
function findEditor() {
  const candidates=[];
  for (const scope of document.querySelectorAll('[role="dialog"],dialog[open]')) {
    if (!visible(scope)) continue;
    const headings=[...scope.querySelectorAll('h1,h2,h3,[role="heading"]')].map(el=>el.textContent).join(' ');
    const label=scope.getAttribute('aria-label')??'';
    const labelled=(scope.getAttribute('aria-labelledby')??'').split(/\s+/).map(id=>document.getElementById(id)?.textContent??'').join(' ');
    if (!/유저\s*노트/.test(`${headings} ${label} ${labelled}`)) continue;
    const editors=[...scope.querySelectorAll('textarea,[contenteditable="true"]')].filter(el=>visible(el)&&!el.disabled&&!el.readOnly&&!el.closest('[data-note-randomizer]'));
    if (editors.length===1) candidates.push({editor:editors[0],scope});
  }
  // Do not guess among multiple editors or use the chat composer.
  return candidates.length===1?candidates[0]:null;
}
function node(tag, attrs={}, text) {
  const el=document.createElement(tag);
  for (const [key,value] of Object.entries(attrs)) { if(key==='class') el.className=value; else el.setAttribute(key,value); }
  if(text!==undefined) el.textContent=text;
  return el;
}
function inputLabel(text, input) {const el=node('label',{class:'field'});el.append(node('span',{},text),input);return el;}
function select(options,value,change) {
  const el=node('select');
  for (const [key,text] of Object.entries(options)) el.append(node('option',{value:key},text));
  el.value=value;el.addEventListener('change',()=>change(el.value));return el;
}
